MasterScript.Script:
int master_script_version = 1;

public bool IsWorkLocation() => GetMonitorCount() == 3;

// Moving a window to an 2nd screen and resizing needs to be done in 2 steps (for some reason)
void MoveAndPlace(string path, int x, int y, int w, int h, int delay)
{
	MoveWindow(path,x,y);
	Sleep(delay);
	MoveWindow(path,x,y,w,h);
}

